#include <cstdio>
#include <iostream>
#include <vector>

using namespace std;

int a[200010];
int pointers[200010][2]; // pointers[0] for prv, pointers[1] for nxt
bool win[200010];

int main(void) {
    int n, m, q;
    scanf("%d %d %d", &n, &m, &q);

    for (int i = 0; i < n; ++i) {
        pointers[i][0] = (i + n - 1) % n; // prv
        pointers[i][1] = (i + 1) % n;     // nxt
        win[i] = true;
    }

    int cur = 0;
    for (int i = 0; i < m; ++i) {
        scanf("%d", &a[i]);
        int direction = (a[i] & 1) ? 0 : 1; // 0 for prv, 1 for nxt
        for (int j = 0; j < a[i]; ++j) {
            cur = pointers[cur][direction];
        }
        win[cur] = false;
        pointers[pointers[cur][0]][1] = pointers[cur][1]; // update nxt of prv
        pointers[pointers[cur][1]][0] = pointers[cur][0]; // update prv of nxt
        cur = pointers[cur][1]; // move to next
    }

    for (int i = 0; i < q; ++i) {
        int in;
        scanf("%d", &in);
        printf("%d\n", win[in]);
    }

    return 0;
}

